function orta(arr) {
  if (arr.length === 0) return 0;
  let s = 0;
  for (const n of arr) s += n;
  return s / arr.length;
}
console.log(orta([4, 6, 8]));

function maxIn(arr) {
  let m = arr[0];
  for (const n of arr) if (n > m) m = n;
  return m;
}
console.log(maxIn([3, 9, 4]));

function countWords(s) {
  const parts = s.trim().split(/\s+/);
  return s.trim() === "" ? 0 : parts.length;
}
console.log(countWords("salom dunyo"));
